    correctKey: 'C',
    explanation: '主任技術者の資格要件は国家資格又は実務経験年数等によって判断されるものであり、雇用期間の長短自体が直接の要件ではない（ただし直接雇用関係は必要）。\n【図解】主任技術者の資格要件\n　★国家資格（1級・2級電気工事施工管理技士等）★\n　★実務経験年数（工事種類・立場等が審査対象）★\n　○直接的かつ恒常的な雇用関係にあることは必要\n　×雇用10年以上が要件（誤り）⚠\n　→ 資格要件は「資格又は実務経験」であり「勤続年数」ではない★',
