    choices: [
      { key: 'A', text: '建築物等の解体又は改修の作業を行う事業者は、当該作業を行う前に、石綿等の使用の有無について、目視、設計図書等の文書による調査及び分析調査等の方法により、事前調査を行わなければならない。', explanation: '適当。事前調査の実施義務である。' },
      { key: 'B', text: '一定規模以上の解体・改修工事については、事前調査の結果を都道府県知事等（労働基準監督署長・都道府県等）へ報告することが義務付けられている。', explanation: '適当。事前調査結果の報告義務である。' },
      { key: 'C', text: '事前調査は、原則として建築物石綿含有建材調査者等、一定の要件を満たす者が行う必要がある場合がある。', explanation: '適当。事前調査の実施者要件である。' },
      { key: 'D', text: '事前調査の結果、石綿等の使用が明らかでない場合には、調査を打ち切り、石綿等が使用されていないものとみなして作業を進めてよい。', explanation: '不適当。事前調査によって石綿等の使用の有無が明らかとならない場合には、当該建築材料に石綿等が「使用されているものとみなして」必要な措置を講ずる必要があるとされており、「使用されていないものとみなして作業を進めてよい」は誤りである（安全側に立った取扱いが求められる）。' },
    ],
    correctKey: 'D',
    explanation: '事前調査で石綿使用の有無が不明な場合は、安全側に立ち「使用されているもの」とみなして対応する点が重要である。\n【図解】石綿事前調査の要点\n　★解体・改修前に目視・設計図書・分析調査等で事前調査を実施★\n　★一定規模以上は調査結果を報告する義務あり\n　★調査は石綿含有建材調査者等が実施（要件あり）\n　×不明な場合は「使用されていない」とみなしてよい（誤り）⚠\n　→ 不明な場合は安全側に立ち「使用されているもの」とみなして対応する★',
    difficulty: 'advanced',
